const { useState, useEffect, useRef, useCallback } = React;

// ── Helpers ───────────────────────────────────────────────────────────────────
const fmt = (n) => new Intl.NumberFormat('es-CL',{style:'currency',currency:'CLP',maximumFractionDigits:0}).format(n||0);
const formatMoneyInput = (value, emptyZero=true) => {
  if(value===''||value===null||value===undefined||(emptyZero&&value===0))return '';
  const numeric=Number(value);
  return Number.isFinite(numeric)?new Intl.NumberFormat('es-CL',{maximumFractionDigits:0,useGrouping:true}).format(numeric):'';
};
const MoneyInput = ({value,onChange,emptyZero=true,placeholder='0',...props}) => {
  const [display,setDisplay]=useState(()=>formatMoneyInput(value,emptyZero));
  const editing=useRef(false);
  useEffect(()=>{if(!editing.current)setDisplay(formatMoneyInput(value,emptyZero));},[value,emptyZero]);
  const change=(event)=>{
    const raw=event.target.value.replace(/\s/g,'');
    if(!/^-?[\d.]*$/.test(raw))return;
    if(raw===''||raw==='-'){
      setDisplay(raw);
      onChange(0);
      return;
    }
    const numeric=Number(raw.replace(/\./g,''));
    if(!Number.isSafeInteger(numeric))return;
    setDisplay(formatMoneyInput(numeric,false));
    onChange(numeric);
  };
  return <input {...props} type="text" inputMode="numeric" placeholder={placeholder} value={display}
    onFocus={()=>{editing.current=true;}}
    onBlur={()=>{editing.current=false;setDisplay(formatMoneyInput(value,emptyZero));}}
    onChange={change}/>;
};
const pct = (a,b) => b ? Math.min(100,Math.round((a/b)*100)) : 0;
const today = () => PeritaApp.civilDate(new Date());
const formatCivilDate = (value) => {
  if(!value)return '—';
  const [year,month,day]=value.split('-').map(Number);
  return new Date(year,month-1,day).toLocaleDateString('es-CL');
};
const presentError = (error) => PeritaApp.userErrorMessage(error);
const monthsLeft = (current,goal,monthly) => {
  if(monthly<=0) return '∞';
  const left = goal - current;
  if(left<=0) return '0';
  return Math.ceil(left/monthly);
};
const addMonths = (n) => {
  const d = new Date();
  d.setMonth(d.getMonth()+n);
  return d.toLocaleDateString('es-CL',{month:'short',year:'numeric'});
};
