const emptyView = () => ({
  settings:{salary:0}, accounts:[], wallets:[], debts:[], budget:[], varCategories:[],
  expenses:[], activeMonth:{month:today().slice(0,7),expenses:[],gastosFijosPagados:[]},
  monthlyHistory:[], operations:[], movements:[], operationRevisions:[], legacyEntries:[],
  summary:null, runtime:null, period:null,
});

const dashboardTotals = (state) => {
  const summary = state.summary || {};
  const totalAvailable = (state.accounts||[]).reduce((sum,item)=>sum+item.balance,0);
  const totalSavings = (state.wallets||[]).reduce((sum,item)=>sum+item.balance,0);
  const totalDebt = (state.debts||[]).reduce((sum,item)=>sum+Math.max(0,item.total-item.paid),0);
  const totalIncomeDash = summary.totalIncomeAmount || 0;
  const monthlySavings = summary.netSavingsAmount || 0;
  return {
    totalAvailable, totalSavings, netWorth:totalAvailable+totalSavings, totalDebt,
    totalIncomeDash, totalVariable:summary.variableExpenseAmount||0,
    monthlySavings, totalFixed:summary.fixedExpensePaidAmount||0,
    monthlyDebt:summary.debtPaymentAmount||0, incomeSrc:totalIncomeDash,
    savingsRate:totalIncomeDash?Math.round((monthlySavings/totalIncomeDash)*100):0,
    remaining:summary.availableAmount||0,
  };
};


