// ── Confirm Dialog ────────────────────────────────────────────────────────────
const ConfirmDialog = ({title, message, confirmLabel='Eliminar', destructive=true, onConfirm, onCancel}) => (
  <div className="modal-backdrop" onClick={onCancel} style={{zIndex:500}}>
    <div className="modal" style={{maxWidth:400}} onClick={e=>e.stopPropagation()}>
      <div className="modal-title">{title}</div>
      <p className="text-sm text-gray mb-6">{message}</p>
      <div className="form-actions">
        <button className="btn btn-ghost" onClick={onCancel}>Cancelar</button>
        <button className={`btn ${destructive?'btn-danger':'btn-primary'}`} onClick={onConfirm}>{confirmLabel}</button>
      </div>
    </div>
  </div>
);

// helper hook
const useConfirm = () => {
  const [dialog, setDialog] = useState(null);
  const ask = (opts) => new Promise(resolve => setDialog({...opts, resolve}));
  const ConfirmNode = dialog ? (
    <ConfirmDialog
      title={dialog.title} message={dialog.message}
      confirmLabel={dialog.confirmLabel} destructive={dialog.destructive}
      onConfirm={()=>{ setDialog(null); dialog.resolve(true); }}
      onCancel={()=>{ setDialog(null); dialog.resolve(false); }}
    />
  ) : null;
  return {ask, ConfirmNode};
};

// ── Unsaved changes guard ─────────────────────────────────────────────────────
const useUnsavedGuard = (isDirty) => {
  const [pendingClose, setPendingClose] = useState(null);

  // Browser/tab close / reload
  useEffect(() => {
    const handler = (e) => {
      if (!isDirty) return;
      e.preventDefault();
      e.returnValue = '';
    };
    window.addEventListener('beforeunload', handler);
    return () => window.removeEventListener('beforeunload', handler);
  }, [isDirty]);

  // Store the requested closer explicitly so confirming discard closes exactly
  // the form that opened the dialog, without depending on a promise/render race.
  const guardClose = useCallback((closeFn) => {
    if (!isDirty) { closeFn(); return; }
    setPendingClose(() => closeFn);
  }, [isDirty]);

  const GuardNode = pendingClose ? <ConfirmDialog
    title="Cambios sin guardar"
    message="Si sales ahora perderás el progreso."
    confirmLabel="Salir"
    destructive={false}
    onConfirm={()=>{
      const close = pendingClose;
      setPendingClose(null);
      close();
    }}
    onCancel={()=>setPendingClose(null)}
  /> : null;

  return {guardClose, GuardNode};
};


