// ── Chart wrapper ─────────────────────────────────────────────────────────────
const ChartCanvas = ({id,config,height=220}) => {
  const ref = useRef(null);
  const chartRef = useRef(null);
  useEffect(()=>{
    if(!ref.current || typeof Chart === 'undefined') return;
    if(chartRef.current) chartRef.current.destroy();
    chartRef.current = new Chart(ref.current, config);
    return ()=>{ if(chartRef.current) chartRef.current.destroy(); };
  }, [JSON.stringify(config)]);
  if(typeof Chart === 'undefined') return (
    <div style={{height:height,display:'flex',alignItems:'center',justifyContent:'center',background:'var(--gray-50)',borderRadius:'var(--radius-sm)',color:'var(--gray-400)',fontSize:13}}>
      Gráfico no disponible en esta previsualización
    </div>
  );
  return <canvas ref={ref} style={{maxHeight:height+'px'}} />;
};

