const StartupCard = ({title,children}) => <div style={{minHeight:'100vh',display:'grid',placeItems:'center',background:'var(--gray-50)',padding:20}}>
  <div className="card" style={{maxWidth:560,width:'100%'}}><div className="modal-title">{title}</div>{children}</div>
</div>;

const RecoveryOverlay = () => <div className="modal-backdrop" style={{zIndex:800}} aria-live="polite" aria-busy="true">
  <div className="modal" style={{maxWidth:360,textAlign:'center'}}>
    <div className="modal-title">Reconectando Perita…</div>
    <p className="text-sm text-gray">Revalidando tus datos y el control seguro de escritura.</p>
  </div>
</div>;

const SetupScreen = ({app,onComplete,notify}) => {
  const [form,setForm]=useState({periodKey:today().slice(0,7),salary:0});
  const [account,setAccount]=useState({name:'Cuenta principal',openingBalance:0});
  const [busy,setBusy]=useState(false);
  const submit=async()=>{
    if(!account.name.trim()){notify('Completa el nombre de la cuenta','warn');return;}
    setBusy(true);
    const timestamp=recordTime();
    try{
      const result=await app.completeSetup({
        currentCivilDate:today(),
        financialSettings:{key:'current',salaryReferenceAmount:form.salary,currency:'CLP',timezone:'America/Santiago',revision:1,createdAt:timestamp,updatedAt:timestamp},
        period:{id:recordId(),periodKey:form.periodKey,status:'open',plannedSalaryAmount:form.salary,openedAt:timestamp,closedAt:null,snapshotId:null,revision:1},
        accounts:[{id:recordId(),name:account.name.trim(),openingBalance:account.openingBalance,currentBalance:account.openingBalance,status:'active',revision:1,createdAt:timestamp,updatedAt:timestamp}],
      });
      if(account.openingBalance<0)notify('Advertencia registrada: la cuenta inicial comienza con saldo negativo','warn');
      await onComplete(result.state);
    }catch(error){notify(presentError(error),'error');}
    finally{setBusy(false);}
  };
  return <StartupCard title="Configurar Perita V1.1.0">
    <p className="text-sm text-gray mb-4">Crea el periodo inicial y una cuenta. Esta confirmación es atómica.</p>
    <div className="form-group"><label className="form-label">Periodo inicial</label><input className="form-input" type="month" value={form.periodKey} onChange={event=>setForm(current=>({...current,periodKey:event.target.value}))}/></div>
    <div className="form-group"><label className="form-label">Sueldo de referencia</label><MoneyInput className="form-input" value={form.salary} onChange={salary=>setForm(current=>({...current,salary}))}/></div>
    <div className="form-label">Cuenta inicial</div>
    <div className="card-sm mb-4">
      <div className="form-group"><label className="form-label">Nombre</label><input autoFocus className="form-input" placeholder="Ej: Cuenta corriente" value={account.name} onChange={event=>setAccount(current=>({...current,name:event.target.value}))}/></div>
      <div className="form-group"><label className="form-label">Saldo inicial</label><MoneyInput className="form-input" value={account.openingBalance} onChange={openingBalance=>setAccount(current=>({...current,openingBalance}))}/></div>
      {account.openingBalance<0&&<div className="alert alert-warn">Esta cuenta comenzará con saldo negativo como excepción de apertura.</div>}
    </div>
    <button className="btn btn-primary w-full" disabled={busy} onClick={submit}>{busy?'Configurando…':'Completar configuración'}</button>
  </StartupCard>;
};

const MigrationScreen = ({app,boot,onComplete,notify}) => {
  const [busy,setBusy]=useState(false);
  const dryRun=boot.dryRun;
  const migrate=async()=>{setBusy(true);try{const result=await app.confirmMigration(dryRun);await onComplete(result.state);}catch(error){notify(presentError(error),'error');}finally{setBusy(false);}};
  return <StartupCard title="Migración V1 → V1.1.0">
    <p className="text-sm text-gray">Clasificación: <strong>{dryRun.classification}</strong></p>
    <p className="text-sm text-gray">Advertencias: {dryRun.warnings?.length||0} · Bloqueos: {dryRun.blockers?.length||0}</p>
    {(dryRun.blockers||[]).map((item,index)=><div key={index} className="alert alert-error mt-2">{presentError(item)}</div>)}
    <p className="text-xs text-gray mt-4">La fuente localStorage["perita_v1"] se conservará intacta. No se crearán movimientos pre-cutover.</p>
    <button className="btn btn-primary w-full mt-4" disabled={busy||dryRun.classification==='blocked'} onClick={migrate}>{busy?'Migrando…':'Confirmar migración'}</button>
  </StartupCard>;
};

const App = () => {
  const [page, setPage] = useState('dashboard');
  const appRef=useRef(null);
  if(!appRef.current) appRef.current=PeritaApp.createPeritaApplication({
    onDeleteBlocked:()=>window.alert('Otra pestaña mantiene abierta la base. Ciérrala y vuelve a intentar.'),
  });
  const app=appRef.current;
  const [boot,setBoot]=useState({phase:'loading'});
  const [state, setStateRaw] = useState(emptyView);
  const [notifs, setNotifs] = useState([]);
  const [updateWaiting, setUpdateWaiting] = useState(null); // holds waiting SW
  const [updateDismissed, setUpdateDismissed] = useState(false);
  const [updateAccepted, setUpdateAccepted] = useState(false);
  const [recovering, setRecovering] = useState(false);
  const lifecycleRef=useRef(null);
  const swUpdatesRef=useRef(null);
  let notifId = useRef(0);

  const notify = useCallback((msg, type='info') => {
    const id = ++notifId.current;
    setNotifs(n=>[...n,{id,msg,type}]);
    setTimeout(()=>setNotifs(n=>n.filter(x=>x.id!==id)), 5000);
  }, []);

  const handleLeaseLost=useCallback(error=>{
    setBoot(current=>({...current,phase:'ready_read_only',writer:false,error}));
    notify('Se perdió el control de escritura; esta pestaña quedó en solo lectura','warn');
  },[notify]);

  const activate=useCallback(async()=>{
    if(lifecycleRef.current) return lifecycleRef.current.resume('setup-completed');
    const initialized=await app.resume();
    setBoot(initialized);
    if(initialized.state)setStateRaw(initialized.state);
    if(initialized.writer)app.startHeartbeat(handleLeaseLost);
    return initialized;
  },[app,handleLeaseLost]);

  useEffect(()=>{
    let active=true;
    const unsubscribe=app.subscribe(next=>{if(active)setStateRaw(next);});
    const lifecycle=PeritaApp.createLifecycleController({
      application:app,
      eventTarget:window,
      visibilitySource:document,
      onRecovering:({reason})=>{if(active&&reason!=='initial')setRecovering(true);},
      onResult:initialized=>{
        if(!active)return;
        swUpdatesRef.current?.check();
        setBoot(initialized);
        if(initialized.state)setStateRaw(initialized.state);
        if(initialized.writer)app.startHeartbeat(handleLeaseLost);
      },
      onError:error=>{
        if(!active)return;
        setBoot({phase:'error',state:null,error:app.errorView(error),writer:false});
      },
      onSettled:()=>{if(active)setRecovering(false);},
    });
    lifecycleRef.current=lifecycle;
    lifecycle.start();
    return()=>{
      active=false;
      lifecycleRef.current=null;
      lifecycle.stop();
      unsubscribe();
    };
  },[app,handleLeaseLost]);

  // Service worker update detection
  useEffect(() => {
    if(!('serviceWorker' in navigator)) return;
    try {
      const updates=PeritaApp.createServiceWorkerUpdateController({
        serviceWorker:navigator.serviceWorker,
        onWaiting:setUpdateWaiting,
        reload:()=>window.location.reload(),
      });
      swUpdatesRef.current=updates;
      updates.start().catch(()=>{});
      return()=>{swUpdatesRef.current=null;updates.stop();};
    } catch(_) {}
  }, []);

  const run=useCallback(async(command,payload,success)=>{
    try{const completed=await app.execute(command,payload);setStateRaw(completed.state);if(success)notify(success,'success');return completed;}
    catch(error){notify(presentError(error),'error');return null;}
  },[app,notify]);

  const setState = useCallback((updater) => {
    if(typeof updater!=='function'&&updater?.runtime){setStateRaw(updater);return Promise.resolve({state:updater});}
    const previous=app.state||state;
    const next=typeof updater==='function'?updater(previous):updater;
    return translateLegacyIntent(app,previous,next).then(result=>{
      if(result?.state)setStateRaw(result.state);
      return result;
    }).catch(error=>{notify(presentError(error),'error');return null;});
  }, [app,state,notify]);

  const dismiss = (id) => setNotifs(n=>n.filter(x=>x.id!==id));

  // Check budget alerts
  useEffect(()=>{
    try {
      const totalBudget = state.budget.reduce((a,b)=>a+b.amount,0);
      const monthlySavings = state.wallets.reduce((a,w)=>a+w.monthly,0);
      if(state.settings.salary>0 && totalBudget + monthlySavings > state.settings.salary){
        const key = 'budget_warned_'+new Date().toDateString();
        if(!sessionStorage.getItem(key)){
          sessionStorage.setItem(key,'1');
          setTimeout(()=>notify('⚠️ Presupuesto + ahorros superan la referencia configurada','warn'),1500);
        }
      }
      state.wallets.forEach(w=>{
        if(w.balance>=w.goal && w.goal>0){
          const key='goal_'+w.id+'_'+new Date().toDateString();
          if(!sessionStorage.getItem(key)){
            sessionStorage.setItem(key,'1');
            setTimeout(()=>notify(`🎉 Meta de ${w.name} alcanzada!`,'success'),2000);
          }
        }
      });
    } catch(_) {}
  },[]);

  const [title,sub] = PAGE_TITLES[page]||['',''];
  const now = new Date();
  const monthLabel = now.toLocaleDateString('es-CL',{month:'long',year:'numeric'});

  const pageProps = {state, setState, notify, run, app};
  const runtimeBannerMessage = ['ready_read_only','read_only'].includes(boot.phase)
    ? 'Otra ventana de Perita está realizando cambios. Puedes esperar o intentar tomar el control.'
    : boot.phase==='diagnostic'
      ? 'Perita necesita una revisión de integridad antes de permitir nuevos cambios.'
      : boot.phase==='restricted'
        ? 'Algunas acciones están temporalmente restringidas. Revisa la integridad antes de continuar.'
        : 'Perita detectó advertencias de integridad. Revisa el estado antes de continuar.';

  useEffect(()=>{
    window.scrollTo({top:0,left:0,behavior:'auto'});
  },[page]);

  if(boot.phase==='loading') return <StartupCard title="Reconectando Perita…"><p className="text-sm text-gray">Leyendo IndexedDB y verificando el runtime…</p></StartupCard>;
  if(boot.phase==='error') return <StartupCard title="No se pudo abrir Perita">
    <div className="alert alert-error">{presentError(boot.error)}</div>
    <p className="text-sm text-gray mt-3">La instancia quedó detenida de forma segura. Reintenta la conexión sin cerrar Perita.</p>
    <button className="btn btn-primary w-full mt-4" disabled={recovering} onClick={()=>lifecycleRef.current?.resume('manual-retry')}>{recovering?'Reconectando…':'Reintentar conexión'}</button>
  </StartupCard>;
  if(boot.phase==='setup_required') return <><Notifs notifs={notifs} dismiss={dismiss}/>{recovering&&<RecoveryOverlay/>}<SetupScreen app={app} notify={notify} onComplete={activate}/></>;
  if(['migration_pending','migration_blocked'].includes(boot.phase)) return <><Notifs notifs={notifs} dismiss={dismiss}/>{recovering&&<RecoveryOverlay/>}<MigrationScreen app={app} boot={boot} notify={notify} onComplete={activate}/></>;

  return (
    <div id="app">
      <Notifs notifs={notifs} dismiss={dismiss} />
      {recovering&&<RecoveryOverlay/>}

      {['ready_read_only','read_only','diagnostic','warning','restricted'].includes(boot.phase) && <div className={`runtime-banner alert ${['warning','restricted'].includes(boot.phase)?'alert-warn':'alert-error'}`}>
        <strong>{boot.phase==='diagnostic'?'Modo diagnóstico':boot.phase==='warning'?'Integridad con advertencias':boot.phase==='restricted'?'Integridad restringida':'Modo solo lectura'}</strong> · {runtimeBannerMessage}
        {['ready_read_only','read_only'].includes(boot.phase)&&<button className="btn btn-ghost btn-sm runtime-banner-action" onClick={async()=>{try{const result=await app.takeOverWriter();setStateRaw(result.state);setBoot({phase:result.report.status==='diagnostic_only'?'diagnostic':result.report.status,state:result.state,report:result.report,writer:true});app.startHeartbeat();notify('Esta pestaña ahora controla la escritura','success');}catch(error){notify(presentError(error),'warn');}}}>Intentar tomar control</button>}
      </div>}

      {/* Mobile bottom nav — Dashboard · Cuentas · Ahorros · Otros · Ajustes */}
      <nav className="mobile-nav">
        {[
          {id:'dashboard',label:'Inicio',icon:'dashboard'},
          {id:'accounts',label:'Cuentas',icon:'accounts'},
          {id:'wallets',label:'Ahorros',icon:'wallet'},
          {id:'other',label:'Otros',icon:'budget'},
          {id:'settings',label:'Ajustes',icon:'settings'},
        ].map(p=>(
          <button key={p.id} className={`mobile-nav-item ${page===p.id?'active':''}`}
            onClick={()=>setPage(p.id)}>
            <Icon name={p.icon} size={18} color={page===p.id?'var(--green)':'var(--gray-400)'} />
            {p.label}
          </button>
        ))}
      </nav>

      {/* Sidebar */}
      <aside className="sidebar">
        <div className="sidebar-logo">
          <div className="logo-mark">
            <div className="logo-icon"><img src={PERITA_LOGO} alt="Perita" style={{width:"100%",height:"100%",objectFit:"cover",display:"block"}} /></div>
            <div><div className="logo-text">Perita</div><div className="logo-sub">Tu dashboard financiero</div></div>
          </div>
        </div>
        <nav className="sidebar-nav">
          <div className="nav-section">
            <div className="nav-label">Principal</div>
            {PAGES.filter(p=>p.id==='dashboard').map(p=>(
              <button key={p.id} className={`nav-item ${page===p.id?'active':''}`} onClick={()=>setPage(p.id)}>
                <Icon name={p.icon} size={15}/>{p.label}
              </button>
            ))}
          </div>
          <div className="nav-section">
            <div className="nav-label">Dinero</div>
            {PAGES.filter(p=>['accounts','wallets'].includes(p.id)).map(p=>(
              <button key={p.id} className={`nav-item ${page===p.id?'active':''}`} onClick={()=>setPage(p.id)}>
                <Icon name={p.icon} size={15}/>{p.label}
              </button>
            ))}
            <button className={`nav-item ${page==='other'?'active':''}`} onClick={()=>setPage('other')}>
              <Icon name="budget" size={15}/>Otros
            </button>
          </div>
          <div className="nav-section">
            <div className="nav-label">Herramientas</div>
            {PAGES.filter(p=>p.id==='settings').map(p=>(
              <button key={p.id} className={`nav-item ${page===p.id?'active':''}`} onClick={()=>setPage(p.id)}>
                <Icon name={p.icon} size={15}/>{p.label}
              </button>
            ))}
          </div>
        </nav>
        <div className="sidebar-footer">
          <div className="month-badge">{monthLabel}</div>
        </div>
      </aside>

      {/* Main */}
      <main className="main">
        <div className="topbar">
          <div>
            <div className="page-title">{title}</div>
            <div className="page-sub">{sub}</div>
          </div>
          <div className="flex items-center gap-2">
            {state.settings.salary>0 && <span className="badge badge-green">Referencia: {fmt(state.settings.salary)}</span>}
          </div>
        </div>
        <div className="content">
          {page==='dashboard' && updateWaiting && !updateDismissed && (
            <div className="card mb-6" role="status" aria-live="polite">
              <div className="flex justify-between items-start gap-4">
                <div>
                  <div className="card-title">Actualización disponible</div>
                  <p className="text-sm text-gray">Hay una nueva versión de Perita lista para instalar. Tus datos no se modificarán.</p>
                </div>
                <span style={{fontSize:28,lineHeight:1}} aria-hidden="true">🐷</span>
              </div>
              <div className="form-actions mt-4">
                <button className="btn btn-ghost" disabled={updateAccepted} onClick={()=>setUpdateDismissed(true)}>Después</button>
                <button className="btn btn-primary" disabled={updateAccepted} onClick={()=>{
                  if(swUpdatesRef.current?.accept(updateWaiting))setUpdateAccepted(true);
                }}>{updateAccepted?'Actualizando…':'Actualizar ahora'}</button>
              </div>
            </div>
          )}
          {page==='dashboard' && <Dashboard {...pageProps} />}
          {page==='accounts' && <AccountsPage {...pageProps} />}
          {page==='wallets' && <Wallets {...pageProps} />}
          {page==='budget' && <Budget {...pageProps} />}
          {page==='expenses' && <ExpenseTracker {...pageProps} />}
          {page==='income' && <IngresosPanel {...pageProps} />}
          {page==='debt' && <DebtTracker {...pageProps} />}
          {page==='history' && <HistorialMensual {...pageProps} />}
          {page==='other' && <OtherPage navigate={setPage} />}
          {page==='settings' && <Settings {...pageProps} />}
        </div>
      </main>
    </div>
  );
};

export default App;
